    } while (in.fire != 1);
    DrawChar(g_text_x, g_text_y, 0x20);
    do {
        in = read_joystick_input(stick);
    } while (in.fire != 0);
    WaitVBL();
    WaitVBL();
    print_string("\n\n\rHold the joystick in the\n\r");
    print_string("lower right\n\r");
    print_string("corner and hit fire:");
    do {
        DrawChar(g_text_x, g_text_y, color);
        WaitVBL();
        WaitVBL();
        WaitVBL();
        if (++color == 0x17)
