{
    char c;

    draw_centered_window(24, 5);
    print_string("  Mouse Configuration   \n\r");
    print_string("  -------------------   \n\r");
    print_string("Choose the sensitivity  \n\r");
    print_string("of the mouse, 1 being   \n\r");
    print_string("slow, 9 being fast:");
    do {
        c = wait_key_cursor() % 256;
        if (c == 27)
