        for n, a in zip(names, self.entries):
            lines.append(';   %-8s %04X' % (n, a))
        for i in instrs:
            if i.addr in labels:
                lines.append('L%04X:' % i.addr)
            lines.append('    ' + repr(i))
        return '\n'.join(lines)

